Office.onReady(() => {
    document.getElementById("insertBtn").onclick = insertTemplate;
});

function showMessage(msg, isError = false) {
    const box = document.getElementById("messageBox");
    if (!box) return;
    box.style.display = "block";
    box.style.borderLeft = isError ? "4px solid #d83b01" : "4px solid #107c10";
    box.style.background = isError ? "#fde7e9" : "#e7f3ec";
    box.innerText = msg;
}

async function insertTemplate() {
    const type = document.getElementById("templateType").value;
    if (!type) return showMessage("⚠️ Vui lòng chọn loại văn bản trước!", true);

    try {
        await Word.run(async (context) => {
            const body = context.document.body;

            // 1. Xóa nội dung cũ và ÁP DỤNG FONT MẶC ĐỊNH cho BODY
            body.clear();

            body.font.set({
                name: "Times New Roman",
                size: 13,
            });
            await context.sync();

            // HTML mẫu
            const html = `
          <div style="font-family:'Times New Roman'; font-size:13pt; line-height:1.3;">
            <table style="width:100%; border-collapse:collapse; margin-bottom:15px; font-size:13pt;">
              <tr>
                <td style="width:50%; text-align:center; vertical-align:top; padding-right:10px;">
                  <p style="margin:0; line-height:1.3; font-size:12pt; text-transform:uppercase;">TÊN CƠ QUAN, TỔ CHỨC CẤP TRÊN (NẾU CÓ)</p>
                  <p style="margin:0; line-height:1.3;"><b style="text-transform:uppercase;"><u>TÊN CƠ QUAN, TỔ CHỨC BAN HÀNH</u></b></p>
                  <p style="margin-top:10pt; line-height:1.3;">Số: .../Ký hiệu văn bản</p>
                </td>
                <td style="width:50%; text-align:center; vertical-align:top; padding-left:10px;">
                  <p style="margin:0; line-height:1.3;"><b style="text-transform:uppercase;">CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</b></p>
                  <p style="margin:0; line-height:1.3;"><b style="font-size:14pt;"><u>Độc lập - Tự do - Hạnh phúc</u></b></p>
                  <p style="margin-top:10pt; line-height:1.3;"><i style="font-size:13pt;">Địa danh, ngày ... tháng ... năm ...</i></p>
                </td>
              </tr>
            </table>
            
            <div style="text-align:center; margin:15px 0;">
              <p style="margin:0; line-height:1.3;"><b style="font-size:14pt; text-transform:uppercase;">${getTitle(type)}</b></p>
              <p style="margin:0; line-height:1.3;"><b style="font-size:14pt;">Về việc .....................................................</b></p>
            </div>

            <div class="content-body" style="margin-top:15px; font-size:13pt; line-height:1.3; text-align:justify;">
              ${getContent(type)}
            </div>

            <table style="width:100%; border-collapse:collapse; margin-top:40px; font-size:13pt;">
              <tr>
                <td style="width:50%; text-align:left; vertical-align:top; padding-left:70px; line-height:1.5;">
                  <p style="margin:0; line-height:1.3;"><b><i>Nơi nhận:</i></b></p>
                  <p style="margin:0; line-height:1.3;">- (Tên đơn vị, cá nhân nhận);</p>
                  <p style="margin:0; line-height:1.3;">- Lưu: VT, ...............</p>
                </td>
                <td style="width:50%; text-align:center; vertical-align:top;">
                  <p style="margin:0; line-height:1.3;"><b style="text-transform:uppercase;">CHỨC VỤ CỦA NGƯỜI KÝ</b></p>
                  <p style="margin:0; line-height:1.3;"><i>(Ký tên, đóng dấu)</i></p>
                  <p style="margin-top:50pt; margin-bottom:0; line-height:1.3;"><b style="font-size:13pt;">HỌ VÀ TÊN</b></p>
                </td>
              </tr>
            </table>
          </div>
        `;

            // 2. Chèn HTML vào Word và đồng bộ
            body.insertHtml(html, Word.InsertLocation.end);
            await context.sync();

            // 3. Tải danh sách paragraphs mới
            const paragraphs = body.paragraphs;
            paragraphs.load("items");
            await context.sync();

            // 4. Áp dụng định dạng đoạn văn cho tất cả các đoạn mới được chèn (Giữ layout, set font cơ bản)
            paragraphs.items.forEach((p) => {
                p.font.set({
                    name: "Times New Roman",
                    size: 13,
                });
                p.spaceAfter = 6;
                p.lineSpacing = 15; // tương đương 1.3 line
            });

            // 5. KHẮC PHỤC TRIỆT ĐỂ: Tìm và ép buộc font cho đoạn "(Ký tên, đóng dấu)"
            const searchText = "(Ký tên, đóng dấu)";
            const searchRanges = body.search(searchText, { matchCase: true });
            searchRanges.load("items");
            await context.sync();

            if (searchRanges.items.length > 0) {
                // Ta chỉ cần xử lý Range đầu tiên
                const kyTenRange = searchRanges.items[0];

                // Áp dụng font và cỡ chữ chuẩn
                kyTenRange.font.set({
                    name: "Times New Roman",
                    size: 13,
                    // **QUAN TRỌNG:** Ép buộc kiểu chữ In Nghiêng (Italic)
                    // để đảm bảo nó không chuyển sang font mặc định của Word.
                    italic: true
                });
            }

            // 6. Đồng bộ cuối cùng để áp dụng các thay đổi
            await context.sync();

            showMessage("✅ Đã chèn mẫu văn bản hành chính thành công. Vấn đề font chữ ký đã được khắc phục!");
        });
    } catch (error) {
        console.error(error);
        showMessage(`❌ Đã xảy ra lỗi: ${error.message || error}.`, true);
    }
}

// ... (các hàm getTitle và getContent giữ nguyên)

function getTitle(type) {
    const map = {
        quyetdinh: "QUYẾT ĐỊNH",
        congvan: "CÔNG VĂN",
        thongbao: "THÔNG BÁO",
        ttrinh: "TỜ TRÌNH",
        baocao: "BÁO CÁO",
        bienban: "BIÊN BẢN",
        kehoach: "KẾ HOẠCH",
        giaymoi: "GIẤY MỜI",
    };
    return map[type] || "VĂN BẢN HÀNH CHÍNH";
}

